package io.aetheris.orchestrator.career;
import org.springframework.stereotype.Service;
import java.util.*;
@Service
public class CareerIntelligenceService {private final CareerAuditRepository repository;public CareerIntelligenceService(CareerAuditRepository repository){this.repository=repository;}public CareerAuditResult audit(CareerAuditRequest r){String role=r.targetRole()==null||r.targetRole().isBlank()?"Software / AI Engineer":r.targetRole().trim();int score=0;List<String> rec=new ArrayList<>();score+=r.githubProfileComplete()?12:0;if(!r.githubProfileComplete())rec.add("Complete GitHub profile identity, bio and recruiter-facing links.");score+=r.profileReadme()?12:0;if(!r.profileReadme())rec.add("Add a concise profile README with strongest projects and evidence.");score+=r.portfolioLinked()?10:0;if(!r.portfolioLinked())rec.add("Link a portfolio from GitHub and public professional profiles.");score+=r.linkedInComplete()?12:0;if(!r.linkedInComplete())rec.add("Complete LinkedIn headline, About, projects, skills and Featured evidence.");score+=Math.min(18,Math.max(0,r.featuredProjects())*6);if(r.featuredProjects()<3)rec.add("Feature at least three interview-ready projects with clear outcomes.");score+=Math.min(14,Math.max(0,r.documentedProjects())*3);if(r.documentedProjects()<3)rec.add("Improve README documentation, architecture and setup instructions.");score+=Math.min(10,Math.max(0,r.projectsWithTests())*3);if(r.projectsWithTests()<2)rec.add("Add automated tests/CI evidence to flagship repositories.");score+=Math.min(7,Math.max(0,r.projectsWithScreenshots())*2);if(r.projectsWithScreenshots()<2)rec.add("Add high-quality screenshots or demos to visual projects.");score+=Math.min(5,Math.max(0,r.skillsCount()/4));score=Math.min(100,score);String findings="Recruiter readiness "+score+"/100 for "+role+". "+(rec.isEmpty()?"Core public evidence is strong; continue measuring project quality and impact.":String.join(" ",rec));CareerAuditEntity entity=repository.save(new CareerAuditEntity(UUID.randomUUID(),role,score,findings));return new CareerAuditResult(entity,List.copyOf(rec));}public List<CareerAuditEntity> recent(){return repository.findTop50ByOrderByCreatedAtDesc();}}
